"use client";

import { cn } from "@/lib/utils";
import { forwardRef, InputHTMLAttributes } from "react";

interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
    label: string;
    error?: string;
    helpText?: string;
}

const Input = forwardRef<HTMLInputElement, InputProps>(
    ({ label, error, helpText, className, ...props }, ref) => {
        return (
            <div className="space-y-1.5 flex flex-col group">
                <label className="text-[12px] font-bold text-slate-700 dark:text-slate-200 tracking-tight flex items-center justify-between">
                    {label}
                </label>
                <div className="relative">
                    <input
                        ref={ref}
                        className={cn(
                            "w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-sm transition-all duration-200",
                            "placeholder:text-slate-400 focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10",
                            "group-hover:border-slate-300 dark:group-hover:border-slate-600",
                            error && "border-rose-500 focus:ring-rose-500/10 focus:border-rose-500",
                            className
                        )}
                        {...props}
                    />
                </div>
                {error ? (
                    <p className="text-[10px] font-bold text-rose-500 px-1 uppercase tracking-tight">
                        {error}
                    </p>
                ) : helpText && (
                    <p className="text-[11px] font-medium text-slate-400 px-1 leading-tight italic">
                        {helpText}
                    </p>
                )}
            </div>
        );
    }
);

Input.displayName = "Input";

export default Input;
